/* R1365 — visible member promotion/event workspace */
(()=>{'use strict';
 const API='https://franklin-navigator-membership.onrender.com',root=document.querySelector('[data-r1365-member-tools]');if(!root)return;
 const q=s=>root.querySelector(s),n=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
 const btn=(text,fn,primary=false)=>{const b=n('button',text,primary?'button primary':'button');b.type='button';b.addEventListener('click',fn);return b};
 const state={me:null,profileId:'',active:false,capabilities:null,promotions:[],media:[],editing:null,busy:false};
 const status=n('p','Checking your member tools…','r37-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');
 const workspace=n('div',undefined,'r1365-workspace');root.append(status,workspace);
 const message=(text,kind='')=>{status.className='r37-status'+(kind?' '+kind:'');status.textContent=text};
 async function request(path,{method='GET',body,headers}={}){let r;try{r=await fetch(API+path,{method,credentials:'include',cache:'no-store',headers:body?{'Content-Type':'application/json',...(headers||{})}:headers,body:body?JSON.stringify(body):undefined})}catch{throw new Error('The member service is temporarily unavailable. Your saved public profile is unchanged.')}let o={};try{o=await r.json()}catch{}if(!r.ok){const e=new Error(o?.error?.message||'We could not complete that request.');e.code=o?.error?.code||'HTTP_'+r.status;throw e}return o}
 async function rawUpload(path,blob){const r=await fetch(API+path,{method:'POST',credentials:'include',cache:'no-store',headers:{'Content-Type':'image/webp','X-Franklin-Rights-Confirmed':'true'},body:blob});let o={};try{o=await r.json()}catch{}if(!r.ok){const e=new Error(o?.error?.message||'The image could not be uploaded.');e.code=o?.error?.code||'HTTP_'+r.status;throw e}return o}
 const activeMembership=me=>['ACTIVE','ACTIVE_CANCELING','GRACE'].includes(String(me?.membership?.status||''))&&me?.membership?.rich_profile===true;
 const friendlyState=s=>({DRAFT:'Draft',SUBMITTED:'In review',PUBLISHED:'Live',CHANGES_REQUESTED:'Needs changes',UNPUBLISHED:'Unpublished',REMOVED:'Removed'}[String(s||'').toUpperCase()]||String(s||'').replaceAll('_',' '));
 const kindLabel=k=>({COUPON:'Coupon',SPECIAL:'Special offer',SALE:'Sale',PROMOTION:'Promotion',EVENT:'Event'}[k]||k);
 const mediaLabel=k=>({COUPON_GRAPHIC:'Coupon graphic',SALE_GRAPHIC:'Sale graphic',PROMOTIONAL_GRAPHIC:'Promotional graphic',PROMOTIONAL_FLYER:'Promotional flyer',EVENT_FLYER:'Event flyer'}[k]||k);
 const dateInput=v=>{if(!v)return'';const d=new Date(v);if(Number.isNaN(d.getTime()))return'';const local=new Date(d.getTime()-d.getTimezoneOffset()*60000);return local.toISOString().slice(0,16)};
 const iso=v=>v?new Date(v).toISOString():null;
 const field=(label,name,type='text',wide=false)=>{const l=n('label',undefined,wide?'wide':'');l.append(n('span',label));const i=document.createElement(type==='textarea'?'textarea':'input');if(type!=='textarea')i.type=type;i.name=name;if(type==='textarea')i.rows=4;l.append(i);return{wrap:l,input:i}};
 const selectField=(label,name,options,wide=false)=>{const l=n('label',undefined,wide?'wide':'');l.append(n('span',label));const s=document.createElement('select');s.name=name;for(const [v,t] of options){const o=n('option',t);o.value=v;s.append(o)}l.append(s);return{wrap:l,input:s}};
 function chooseProfile(){const wanted=new URLSearchParams(location.search).get('profile');const links=state.me?.profileLinks||[];const verified=links.filter(x=>x.authority_state==='VERIFIED');const memberId=state.me?.membership?.profile_id;state.profileId=(wanted&&verified.some(x=>x.profile_id===wanted)?wanted:'')||(memberId&&verified.some(x=>x.profile_id===memberId)?memberId:'')||verified[0]?.profile_id||'';state.active=activeMembership(state.me)&&state.me?.membership?.profile_id===state.profileId}
 async function refresh(){state.me=await request('/api/accounts/me').catch(e=>e.code==='AUTH_REQUIRED'?null:Promise.reject(e));if(!state.me){renderSignedOut();return}chooseProfile();if(!state.profileId){renderNoProfile();return}if(!state.active){renderLocked();return}const [caps,promos,media]=await Promise.all([request('/api/member/promotions/capabilities'),request('/api/member/promotions/list?profileId='+encodeURIComponent(state.profileId)),request('/api/member/promotions/media/list?profileId='+encodeURIComponent(state.profileId))]);state.capabilities=caps;state.promotions=promos.promotions||[];state.media=media.media||[];renderActive();message('Community Member tools are ready. Create or manage profile promotions below.','good')}
 function renderSignedOut(){workspace.replaceChildren();const box=n('section',undefined,'r1365-tools-intro');box.append(n('h2','Your profile tools'),n('p','Sign in to Profile Center to manage a verified Franklin profile. Basic profile management stays free; coupons, promotions, events and promotional graphics are Community Membership tools.'));const a=n('div',undefined,'actions');const x=n('a','Sign in / manage profile','button primary');x.href='/profile-access/';a.append(x);box.append(a);workspace.append(box);message('Sign in to use profile management tools.')}
 function renderNoProfile(){workspace.replaceChildren();const box=n('section',undefined,'r1365-tools-intro');box.append(n('h2','Connect your profile first'),n('p','These tools attach to a verified Franklin business or organization profile. Claiming and verification remain free.'));const a=n('a','Find or verify my profile','button primary');a.href='/profile-access/';box.append(a);workspace.append(box);message('No verified profile is connected to this account.')}
 function toolCards(locked=false){const grid=n('div',undefined,'r1365-tools-grid');const cards=[['Coupons & specials','Create a coupon or special offer with dates, code, terms and a customer action link.','COUPON'],['Sales & promotions','Publish reviewed sale and promotional information directly on your Franklin profile.','SALE'],['Events','Add reviewed event details, dates, location and an event flyer.','EVENT'],['Promotional graphics & flyers','Attach reviewed WebP coupon graphics, sale graphics, promotional graphics and flyers.','MEDIA']];for(const [h,p,k] of cards){const c=n('article',undefined,'r1365-tool-card r1365-visually-important'+(locked?' r1365-locked':''));c.append(n('h3',h),n('p',p));if(locked){const a=n('a','See Community Membership — $35/year','button');a.href='/membership-start/?profile='+encodeURIComponent(state.profileId);c.append(a)}else{c.append(btn(k==='MEDIA'?'Manage with a promotion':'Create '+h.toLowerCase(),()=>{if(k==='MEDIA'){q('#r1365-promotion-list')?.scrollIntoView({behavior:'smooth'});message('Choose a promotion below, then add its promotional image or flyer.')}else startCreate(k)},k!=='MEDIA'))}grid.append(c)}return grid}
 function renderLocked(){workspace.replaceChildren();const box=n('section',undefined,'r1365-tools-intro');box.append(n('div','Optional Community Membership','eyebrow'),n('h2','Member visibility tools are easy to find here.'),n('p','Your verified profile can still be managed for free. Community Membership is optional at $35/year and unlocks the reviewed promotional tools shown below.'));box.append(toolCards(true));const a=n('div',undefined,'actions');const free=n('a','Continue free profile management','button primary');free.href='/profile-studio/?profile='+encodeURIComponent(state.profileId);a.append(free);box.append(a);workspace.append(box);message('Free profile management is available. Promotional tools require active Community Membership.')}
 function renderActive(){workspace.replaceChildren();const intro=n('section',undefined,'r1365-tools-intro');intro.append(n('div','Community Member tools','eyebrow'),n('h2','Manage what Franklin residents can see on your profile.'),n('p','Create offers, sales, promotions and events here. Save a draft, add an optional image or flyer, then submit it for review. Approved current items appear on your public profile automatically.'));intro.append(toolCards(false));workspace.append(intro);const shell=n('section',undefined,'r1365-workspace');shell.id='r1365-promotion-workspace';const head=n('div',undefined,'r1365-workspace-head');head.append(n('div',undefined));head.firstChild.append(n('div','Profile promotions','eyebrow'),n('h3','Coupons, specials, sales, promotions & events'));head.append(btn('Create new',()=>startCreate('COUPON'),true));shell.append(head,renderForm(),renderList());workspace.append(shell)}
 function startCreate(kind){state.editing={kind:kind==='SALE'?'SALE':kind==='EVENT'?'EVENT':'COUPON'};renderActive();const form=q('#r1365-promotion-form');if(form){form.scrollIntoView({behavior:'smooth',block:'start'});form.querySelector('[name="title"]')?.focus()}}
 function startEdit(row){state.editing=row;renderActive();setTimeout(()=>q('#r1365-promotion-form')?.scrollIntoView({behavior:'smooth',block:'start'}),0)}
 function renderForm(){const wrap=n('div');if(!state.editing){wrap.append(n('p','Choose a tool above or use “Create new” to add a profile promotion.','r1365-inline-note'));return wrap}const row=state.editing,editing=Boolean(row.promotion_id),form=n('form',undefined,'r1365-promo-form');form.id='r1365-promotion-form';const kind=selectField('Type','kind',[['COUPON','Coupon'],['SPECIAL','Special offer'],['SALE','Sale'],['PROMOTION','Promotion'],['EVENT','Event']]);const title=field('Title','title');const desc=field('Description','description','textarea',true);const code=field('Coupon / promo code','promoCode');const discount=field('Discount or offer summary','discountText');const action=field('Customer action link','actionUrl','url',true);const start=field('Starts','startAt','datetime-local');const end=field('Ends / expires','endAt','datetime-local');const locationField=field('Event location','eventLocation','text',true);form.append(kind.wrap,title.wrap,desc.wrap,code.wrap,discount.wrap,action.wrap,start.wrap,end.wrap,locationField.wrap);kind.input.value=row.kind||'COUPON';title.input.value=row.title||'';desc.input.value=row.description||'';code.input.value=row.promo_code||row.promoCode||'';discount.input.value=row.discount_text||row.discountText||'';action.input.value=row.action_url||row.actionUrl||'';start.input.value=dateInput(row.start_at||row.startAt);end.input.value=dateInput(row.end_at||row.endAt);locationField.input.value=row.event_location||row.eventLocation||'';const actions=n('div',undefined,'wide r1365-promo-actions');const save=n('button',editing?'Save draft changes':'Save draft','button primary');save.type='submit';actions.append(save,btn('Cancel',()=>{state.editing=null;renderActive()}));form.append(actions);form.addEventListener('submit',e=>{e.preventDefault();work(async()=>{const body={kind:kind.input.value,title:title.input.value,description:desc.input.value,promoCode:code.input.value,discountText:discount.input.value,actionUrl:action.input.value,startAt:iso(start.input.value),endAt:iso(end.input.value),eventLocation:locationField.input.value};if(editing){body.promotionId=row.promotion_id;body.expectedRevision=Number(row.revision);await request('/api/member/promotions/update?profileId='+encodeURIComponent(state.profileId),{method:'POST',body})}else await request('/api/member/promotions/create?profileId='+encodeURIComponent(state.profileId),{method:'POST',body:{...body,idempotencyKey:crypto.randomUUID()}});state.editing=null;await reloadData();message('Draft saved. Add an optional image or flyer, then submit for review.','good')})});return form}
 function mediaFor(id){return state.media.filter(x=>x.promotion_id===id)}
 function renderList(){const out=n('div',undefined,'r1365-promo-list');out.id='r1365-promotion-list';if(!state.promotions.length){out.append(n('p','No promotions yet. Create your first coupon, special, sale, promotion or event above.'));return out}for(const row of state.promotions){const card=n('article',undefined,'r1365-promo-item');const meta=n('div',undefined,'r1365-promo-meta');meta.append(n('span',kindLabel(row.kind),'eyebrow'),n('span',friendlyState(row.state),'r1365-state'));card.append(meta,n('h4',row.title),n('p',row.description));const info=n('div',undefined,'r1365-promo-meta');if(row.promo_code)info.append(n('span','Code: '+row.promo_code));if(row.discount_text)info.append(n('span',row.discount_text));if(row.start_at)info.append(n('span','Starts '+new Date(row.start_at).toLocaleString()));if(row.end_at)info.append(n('span','Ends '+new Date(row.end_at).toLocaleString()));if(row.event_location)info.append(n('span',row.event_location));card.append(info);if(row.public_reason)card.append(n('p','Review note: '+row.public_reason,'r37-status warn'));const actions=n('div',undefined,'r1365-promo-actions');if(['DRAFT','CHANGES_REQUESTED','UNPUBLISHED'].includes(row.state)){actions.append(btn('Edit',()=>startEdit(row)),btn('Submit for review',()=>work(async()=>{await request('/api/member/promotions/submit?profileId='+encodeURIComponent(state.profileId),{method:'POST',body:{promotionId:row.promotion_id}});await reloadData();message('Submitted for review. It will not appear publicly until approved.','good')}),true))}if(row.state==='PUBLISHED')actions.append(btn('Unpublish',()=>work(async()=>{await request('/api/member/promotions/unpublish?profileId='+encodeURIComponent(state.profileId),{method:'POST',body:{promotionId:row.promotion_id}});await reloadData();message('Promotion unpublished.','good')})));if(row.state!=='SUBMITTED')actions.append(btn('Remove',()=>{if(confirm('Remove this promotion from your profile tools?'))work(async()=>{await request('/api/member/promotions/remove?profileId='+encodeURIComponent(state.profileId),{method:'POST',body:{promotionId:row.promotion_id}});await reloadData();message('Promotion removed.','good')})}));card.append(actions,renderMedia(row));out.append(card)}return out}
 function renderMedia(row){const box=n('div',undefined,'r1365-media-box');box.append(n('h4','Promotional image or flyer'));const existing=mediaFor(row.promotion_id),list=n('div',undefined,'r1365-media-list');for(const m of existing){const line=n('div',undefined,'r1365-media-row');line.append(n('span',mediaLabel(m.media_kind)+' · '+friendlyState(m.state)));const acts=n('div',undefined,'r1365-promo-actions');const preview=n('a','Preview','button');preview.href=API+m.previewUrl;preview.target='_blank';preview.rel='noopener';acts.append(preview);if(['DRAFT','CHANGES_REQUESTED'].includes(m.state))acts.append(btn('Submit image for review',()=>work(async()=>{await request('/api/member/promotions/media/submit?profileId='+encodeURIComponent(state.profileId),{method:'POST',body:{promotionId:row.promotion_id,mediaId:m.media_id}});await reloadData();message('Promotional image submitted for review.','good')}),true));if(m.state!=='SUBMITTED')acts.append(btn('Remove image',()=>work(async()=>{await request('/api/member/promotions/media/remove?profileId='+encodeURIComponent(state.profileId),{method:'POST',body:{promotionId:row.promotion_id,mediaId:m.media_id}});await reloadData()})));line.append(acts);list.append(line)}if(existing.length)box.append(list);if(row.state==='SUBMITTED'){box.append(n('p','Promotion review is pending. Add or change media after the promotion returns to an editable state.','fine-print'));return box}const mediaKind=selectField('Image type','mediaKind',[['COUPON_GRAPHIC','Coupon graphic'],['SALE_GRAPHIC','Sale graphic'],['PROMOTIONAL_GRAPHIC','Promotional graphic'],['PROMOTIONAL_FLYER','Promotional flyer'],['EVENT_FLYER','Event flyer']]);const file=field('Choose image','file','file');file.input.accept='image/jpeg,image/png,image/webp';const rights=n('label',undefined,'p0-check'),check=document.createElement('input');check.type='checkbox';rights.append(check,document.createTextNode(' I own this image or have permission to publish it.'));const upload=btn('Upload image',()=>work(async()=>{if(!check.checked)throw new Error('Confirm that you own the image or have permission to publish it.');const selected=file.input.files?.[0];if(!selected)throw new Error('Choose an image first.');const blob=await toWebp(selected);await rawUpload('/api/member/promotions/media/upload?profileId='+encodeURIComponent(state.profileId)+'&promotionId='+encodeURIComponent(row.promotion_id)+'&mediaKind='+encodeURIComponent(mediaKind.input.value),blob);await reloadData();message('Image saved as a draft. Submit it for review when ready.','good')}),true);const form=n('div',undefined,'r1365-promo-form');form.append(mediaKind.wrap,file.wrap,rights);const a=n('div',undefined,'wide r1365-promo-actions');a.append(upload);form.append(a);box.append(form,n('p','Images are prepared as WebP for safe display. PDF uploads are not currently supported.','fine-print'));return box}
 async function toWebp(file){if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw new Error('Choose a JPG, PNG or WebP image.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,3000/bitmap.width,3000/bitmap.height,Math.sqrt(9000000/(bitmap.width*bitmap.height)));const w=Math.max(1,Math.round(bitmap.width*scale)),h=Math.max(1,Math.round(bitmap.height*scale)),canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d',{alpha:false}).drawImage(bitmap,0,0,w,h);bitmap.close?.();const blob=await new Promise(r=>canvas.toBlob(r,'image/webp',.88));if(!blob)throw new Error('Your browser could not prepare this image.');if(blob.size>4*1024*1024)throw new Error('The prepared image is still larger than 4 MB. Choose a smaller image.');return blob}
 async function reloadData(){const [promos,media]=await Promise.all([request('/api/member/promotions/list?profileId='+encodeURIComponent(state.profileId)),request('/api/member/promotions/media/list?profileId='+encodeURIComponent(state.profileId))]);state.promotions=promos.promotions||[];state.media=media.media||[];renderActive()}
 async function work(fn){if(state.busy)return;state.busy=true;root.setAttribute('aria-busy','true');try{await fn()}catch(e){message(e.message||'We could not complete that request.','warn')}finally{state.busy=false;root.removeAttribute('aria-busy')}}
 refresh().catch(e=>{message(e.message||'Member tools could not load.','warn');workspace.replaceChildren()});
})();
